from pathlib import Path
import base64,hashlib
base=Path.home()/"tj23114/packages/dachuang_ztd/ZhouSiyu_DF_GAN_20261117"
p=base/"uploads/20261122_generative_full_v04_code.tar.gz.part"
assert p.resolve().is_relative_to(base.resolve())
b=base64.b64decode('')
offset=0
size=p.stat().st_size if p.exists() else 0
if size==offset:
 with p.open("ab") as f:f.write(b)
elif size>=offset+len(b):
 with p.open("rb") as f:f.seek(offset);assert f.read(len(b))==b
else:raise ValueError("Upload offset mismatch")
print('RUNTIME_V04_CHUNK_0_OK',flush=True)
